definition.script:
String normalizeBranchSpec(String branch)
{
    String value = branch?.trim()
    if (!value) {
        return '*/main'
    }

    value = value.replaceFirst('^refs/heads/', '')
    value = value.replaceFirst('^origin/', '')
    return value.startsWith('*/') ? value : "*/${value}"
}

pipeline {
    agent {
        node {
            label 'built-in'
        }
    }

    options {
        skipDefaultCheckout(true)
        disableConcurrentBuilds()
        lock(resource: 'headsling-unity-macos')
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timeout(time: 180, unit: 'MINUTES')
        timestamps()
    }

    parameters {
        choice(name: 'SOURCE_MODE', choices: ['LOCAL_SNAPSHOT', 'GIT'], description: 'Local snapshot includes saved, unpushed source changes; Git builds the selected branch.')
        string(name: 'LOCAL_SOURCE_PATH', defaultValue: '/Users/daisei/HeadGame', description: 'Read-only source for LOCAL_SNAPSHOT. Caches and credentials are excluded.')
        string(name: 'BRANCH', defaultValue: 'main', description: 'Git branch for GIT mode. The branch must use the dedicated HEADSLING asset bucket.')
        choice(name: 'UNITY_VERSION', choices: ['6000.5.1f1'], description: 'Unity version; must match ProjectVersion.txt.')
        string(name: 'APP_VERSION', defaultValue: '1.0', description: 'Android versionName.')
        string(name: 'VERSION_CODE', defaultValue: '', description: 'Positive Android versionCode; blank uses Jenkins BUILD_NUMBER.')
        choice(name: 'ARTIFACT_FORMAT', choices: ['APK', 'AAB'], description: 'APK for direct installation; AAB for bundle validation or Google Play.')
        choice(name: 'SIGNING', choices: ['Debug', 'Release'], description: 'Debug supports test APK/AAB builds; Google Play uploads must use Release.')
        booleanParam(name: 'UPLOAD_GOOGLE_PLAY', defaultValue: false, description: 'Upload and publish a Release AAB to all eligible internal testers on Google Play.')
        text(name: 'GOOGLE_PLAY_RELEASE_NOTES', defaultValue: '', description: 'Optional zh-CN release notes (maximum 500 characters). A build-specific default is used when blank.')
        booleanParam(name: 'CLEAN_LIBRARY', defaultValue: false, description: 'Delete the Unity Library cache before building.')
    }

    environment {
        HEADSLING_BUILD_TARGET = 'Android'
        APP_BUNDLE_ID = 'com.headsling.prototype'
    }

    stages {
        stage('Checkout') {
            steps {
                script {
                    env.HEADSLING_SOURCE_MODE = params.SOURCE_MODE ?: 'LOCAL_SNAPSHOT'
                    env.HEADSLING_SOURCE_PROJECT = params.LOCAL_SOURCE_PATH?.trim() ?: '/Users/daisei/HeadGame'
                    env.HEADSLING_BRANCH = normalizeBranchSpec(params.BRANCH?.toString())
                    if (!(env.HEADSLING_SOURCE_MODE in ['LOCAL_SNAPSHOT', 'GIT'])) {
                        error('SOURCE_MODE must be LOCAL_SNAPSHOT or GIT.')
                    }
                    if (env.HEADSLING_SOURCE_MODE == 'LOCAL_SNAPSHOT') {
                        sh '''#!/bin/bash
set -euo pipefail
test -f "$HEADSLING_SOURCE_PROJECT/tools/ci/prepare-solo-workspace.py"
# The helper only writes the distinct Jenkins WORKSPACE and never the source.
# Preserve this job's Library here; CLEAN_LIBRARY remains in Preflight.
python3 "$HEADSLING_SOURCE_PROJECT/tools/ci/prepare-solo-workspace.py" \
  --source "$HEADSLING_SOURCE_PROJECT" --workspace "$WORKSPACE" --preserve-library
'''
                    } else {
                        checkout([
                            $class: 'GitSCM',
                            branches: [[name: env.HEADSLING_BRANCH]],
                            doGenerateSubmoduleConfigurations: false,
                            extensions: [[$class: 'LocalBranch', localBranch: '**']],
                            userRemoteConfigs: [[
                                credentialsId: 'bodacheng',
                                url: 'https://github.com/bodacheng/HeadGame.git'
                            ]]
                        ])
                        sh '''#!/bin/bash
set -euo pipefail
test -f tools/ci/prepare-solo-workspace.py
# Remove any source left by an earlier local snapshot; retain ignored caches.
git reset --hard HEAD >/dev/null
git clean -fd >/dev/null
rm -rf "$WORKSPACE/Logs/Jenkins"
python3 tools/ci/prepare-solo-workspace.py --source "$WORKSPACE" --inspect-only
'''
                    }
                    env.HEADSLING_GIT_REVISION = sh(returnStdout: true, script: '''#!/bin/bash
set -euo pipefail
python3 - <<'PY'
import json, os, re
with open('Logs/Jenkins/source-snapshot.json', encoding='utf-8') as stream:
    receipt = json.load(stream)
revision = receipt.get('sourceGitRevision')
dirty = receipt.get('sourceDirty')
dirty_hash = receipt.get('sourceDirtyHash')
if not isinstance(revision, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', revision):
    raise SystemExit('Invalid source Git revision in receipt.')
if type(dirty) is not bool or (dirty and (not isinstance(dirty_hash, str) or not re.fullmatch(r'[0-9a-f]{64}', dirty_hash))):
    raise SystemExit('Invalid source dirty fingerprint in receipt.')
if os.environ['HEADSLING_SOURCE_MODE'] == 'GIT' and dirty:
    raise SystemExit('Git source must be clean; refusing mixed source from an earlier workspace run.')
print(revision + (':dirty:' + dirty_hash if dirty else ''))
PY
''').trim()
                }
            }
        }

        stage('Preflight') {
            steps {
                script {
                    def requiredBuildFiles = ['Assets/Editor/HeadSlingCIBuild.cs', 'tools/ci/verify-addressables.py', 'tools/ci/redact-build-log.py', 'Assets/Resources/HeadSling/solo-content-settings.json']
                    def missingBuildFiles = requiredBuildFiles.findAll { !fileExists(it) }
                    if (missingBuildFiles) {
                        error("Branch ${env.HEADSLING_BRANCH} is missing CI build files: ${missingBuildFiles.join(', ')}. Merge the mobile pipeline changes into that branch before building.")
                    }
                    if (!(params.APP_VERSION ==~ /^[0-9]+([.][0-9]+){0,2}$/)) {
                        error("APP_VERSION must contain one to three numeric components: ${params.APP_VERSION}")
                    }
                    String projectUnityVersion = readFile('ProjectSettings/ProjectVersion.txt')
                        .readLines()
                        .find { it.startsWith('m_EditorVersion:') }
                        ?.split(':', 2)?.last()?.trim()
                    env.HEADSLING_UNITY_VERSION = params.UNITY_VERSION?.toString()?.trim() ?: projectUnityVersion
                    if (!env.HEADSLING_UNITY_VERSION) {
                        error('Unable to resolve a Unity version.')
                    }
                    if (projectUnityVersion && projectUnityVersion != env.HEADSLING_UNITY_VERSION) {
                        error("Project requires Unity ${projectUnityVersion}; selected ${env.HEADSLING_UNITY_VERSION}.")
                    }
                    env.HEADSLING_CI_RUN_ID = env.BUILD_TAG
                    // Make newly introduced parameters available to shell steps on a job's first run.
                    env.ARTIFACT_FORMAT = params.ARTIFACT_FORMAT ?: 'APK'
                    env.SIGNING = params.SIGNING ?: 'Debug'
                    env.UPLOAD_GOOGLE_PLAY = (params.UPLOAD_GOOGLE_PLAY ?: false).toString()
                    if (params.UPLOAD_GOOGLE_PLAY && (env.ARTIFACT_FORMAT != 'AAB' || env.SIGNING != 'Release')) {
                        error('UPLOAD_GOOGLE_PLAY requires ARTIFACT_FORMAT=AAB and SIGNING=Release.')
                    }
                    String releaseNotes = params.GOOGLE_PLAY_RELEASE_NOTES?.trim()
                    if (releaseNotes?.length() > 500) {
                        error('GOOGLE_PLAY_RELEASE_NOTES must not exceed 500 characters.')
                    }
                    String versionCode = params.VERSION_CODE?.trim() ?: env.BUILD_NUMBER
                    if (!(versionCode ==~ /^[1-9][0-9]{0,9}$/) || versionCode.toLong() > 2100000000L) {
                        error('VERSION_CODE must be between 1 and 2100000000.')
                    }
                    env.HEADSLING_BUILD_NUMBER = versionCode
                    currentBuild.description = "Version: ${params.APP_VERSION}\nBuild: ${env.BUILD_NUMBER}\nSource: ${env.HEADSLING_SOURCE_MODE}\nBranch: ${env.HEADSLING_BRANCH}\nUnity: ${env.HEADSLING_UNITY_VERSION}\nGit: ${env.HEADSLING_GIT_REVISION}"
                }
                sh '''#!/bin/bash
set -euo pipefail
UNITY_ROOT="/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}"
test -x "$UNITY_ROOT/Unity.app/Contents/MacOS/Unity"
test -x "$UNITY_ROOT/PlaybackEngines/AndroidPlayer/OpenJDK/bin/java"
test -d "$UNITY_ROOT/PlaybackEngines/AndroidPlayer/SDK"
test -d "$UNITY_ROOT/PlaybackEngines/AndroidPlayer/NDK"
command -v python3 >/dev/null

# Refuse an older Git branch or local source that still embeds the shared bucket.
python3 - <<'PY'
import json
with open('Assets/Resources/HeadSling/solo-content-settings.json', encoding='utf-8') as stream:
    settings = json.load(stream)
expected = 'https://headsling-assets-664894817585.s3.ap-northeast-1.amazonaws.com/release/headsling/config/v1'
if settings.get('RemoteCatalogRoot') != expected:
    raise SystemExit('Source must use the dedicated HEADSLING bucket RemoteCatalogRoot: ' + expected)
PY

if [ "$CLEAN_LIBRARY" = true ]; then rm -rf "$WORKSPACE/Library"; fi
rm -rf "$WORKSPACE/Builds/Android"
# Keep the source receipt while clearing old build and verification logs.
if [ -d "$WORKSPACE/Logs/Jenkins" ]; then
    find "$WORKSPACE/Logs/Jenkins" -mindepth 1 -maxdepth 1 ! -name source-snapshot.json -exec rm -rf {} +
fi
mkdir -p "$WORKSPACE/Builds/Android" "$WORKSPACE/Logs/Jenkins"
'''
            }
        }

        stage('Build Addressables (Android)') {
            steps {
                sh '''#!/bin/bash
set -euo pipefail
UNITY_EXECUTABLE="/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}/Unity.app/Contents/MacOS/Unity"
HEADSLING_APP_VERSION="$APP_VERSION" \
"$UNITY_EXECUTABLE" -projectPath "$WORKSPACE" -quit -batchmode -nographics \
  -buildTarget Android -executeMethod HeadSling.Editor.HeadSlingCIBuild.BuildAddressables \
  -logFile "$WORKSPACE/Logs/Jenkins/addressables_android_${BUILD_NUMBER}.log"
test -s "$WORKSPACE/Logs/Jenkins/addressables-Android.json"
'''
            }
        }

        stage('Build Android') {
            steps {
                script {
                    def buildAndroid = {
                        sh '''#!/bin/bash
set -euo pipefail
UNITY_EXECUTABLE="/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}/Unity.app/Contents/MacOS/Unity"
UNITY_LOG="$WORKSPACE/Logs/Jenkins/android_${BUILD_NUMBER}.log"
trap 'python3 tools/ci/redact-build-log.py "$UNITY_LOG"' EXIT
HEADSLING_PREBUILT_ADDRESSABLES=true \
HEADSLING_BUNDLE_ID="$APP_BUNDLE_ID" \
HEADSLING_APP_VERSION="$APP_VERSION" \
HEADSLING_ANDROID_FORMAT="$ARTIFACT_FORMAT" \
HEADSLING_ANDROID_SIGNING="$SIGNING" \
"$UNITY_EXECUTABLE" -projectPath "$WORKSPACE" -quit -batchmode -nographics \
  -buildTarget Android -executeMethod HeadSling.Editor.HeadSlingMobileBuilder.BuildAndroid \
  -logFile "$WORKSPACE/Logs/Jenkins/android_${BUILD_NUMBER}.log"
'''
                    }
                    if (params.SIGNING == 'Release') {
                        withCredentials([
                            file(credentialsId: 'HEADSLING_ANDROID_KEYSTORE', variable: 'HEADSLING_ANDROID_KEYSTORE'),
                            string(credentialsId: 'HEADSLING_ANDROID_STORE_PASSWORD', variable: 'HEADSLING_ANDROID_STORE_PASSWORD'),
                            string(credentialsId: 'HEADSLING_ANDROID_KEY_ALIAS', variable: 'HEADSLING_ANDROID_KEY_ALIAS'),
                            string(credentialsId: 'HEADSLING_ANDROID_KEY_PASSWORD', variable: 'HEADSLING_ANDROID_KEY_PASSWORD')
                        ]) { buildAndroid() }
                    } else {
                        buildAndroid()
                    }
                }
            }
        }

        stage('Verify Android Artifact') {
            steps {
                sh '''#!/bin/bash
set -euo pipefail
EXTENSION="$(printf '%s' "$ARTIFACT_FORMAT" | tr '[:upper:]' '[:lower:]')"
ARTIFACT="Builds/Android/HEADSLING.$EXTENSION"
test -s "$ARTIFACT"
python3 tools/ci/verify-addressables.py Logs/Jenkins/addressables-Android.json "$ARTIFACT" \
  --output Logs/Jenkins/addressables-android-artifact-check.json
UNITY_ANDROID="/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}/PlaybackEngines/AndroidPlayer"
if [ "$ARTIFACT_FORMAT" = APK ]; then
    APKSIGNER="$(find "$UNITY_ANDROID/SDK/build-tools" -name apksigner.jar -print | sort | tail -n 1)"
    test -n "$APKSIGNER"
    "$UNITY_ANDROID/OpenJDK/bin/java" -jar "$APKSIGNER" verify --print-certs "$ARTIFACT" \
      > Logs/Jenkins/android-signature.txt
else
    # Java uses the macOS UI language instead of LC_ALL for this output. Force
    # English so a valid bundle does not fail verification on localized agents.
    "$UNITY_ANDROID/OpenJDK/bin/jarsigner" -J-Duser.language=en -J-Duser.country=US \
      -verify "$ARTIFACT" > Logs/Jenkins/android-signature.txt
    grep -q '^jar verified[.]$' Logs/Jenkins/android-signature.txt
fi
shasum -a 256 "$ARTIFACT" > "$ARTIFACT.sha256"
'''
            }
        }

        stage('Archive Android Artifact') {
            steps {
                archiveArtifacts(artifacts: 'Builds/Android/*', fingerprint: true, followSymlinks: false)
            }
        }

        stage('Upload Google Play') {
            when {
                expression { params.UPLOAD_GOOGLE_PLAY ?: false }
            }
            steps {
                script {
                    String releaseNotes = params.GOOGLE_PLAY_RELEASE_NOTES?.trim() ?:
                        "HEADSLING internal build ${env.HEADSLING_BUILD_NUMBER}."
                    androidApkUpload(
                        filesPattern: 'Builds/Android/HEADSLING.aab',
                        googleCredentialsId: 'GemWarrior',
                        recentChangeList: [[
                            language: 'zh-CN',
                            text: releaseNotes
                        ]],
                        releaseName: "${params.APP_VERSION} (${env.HEADSLING_BUILD_NUMBER})",
                        rolloutPercentage: '100',
                        trackName: 'internal'
                    )
                }
            }
        }
    }

    post {
        always {
            archiveArtifacts(allowEmptyArchive: true,
                artifacts: 'Logs/Jenkins/**, Logs/AndroidBuildSummary.txt, Assets/AddressableAssetsData/Android/addressables_content_state.bin',
                fingerprint: true, followSymlinks: false)
        }
    }
}
